-- Slow app launch fix
-- Generated by hyprlang2lua. Review TODOs before reloading Hyprland.

-- Delay waybar to ensure Hyprland IPC is ready

--##### --------------------- ######
--#####    AUTOSTART APPS     ######
--##### --------------------- ######

-- exec-once = zen-browser
-- exec-once = spotify-launcher
-- exec-once = vesktop
-- exec-once = Telegram
-- exec-once = kitty -e tmux new -As Practice 'nvim'

hl.on("hyprland.start", function()
    hl.exec_cmd("dbus-update-activation-environment --systemd --all")
    hl.exec_cmd("systemctl --user import-environment $(env | cut -d'=' -f1)")
    hl.exec_cmd("uwsm-app -- wl-clip-persist --clipboard regular &")
    hl.exec_cmd("/usr/lib/polkit-gnome/polkit-gnome-authentication-agent-1")
    hl.exec_cmd("uwsm-app -- wl-paste --watch cliphist store")
    hl.exec_cmd("uwsm-app -- awww-daemon")
    hl.exec_cmd("uwsm-app -- hypridle")
    hl.exec_cmd("uwsm-app -- swayosd-server")
    hl.exec_cmd("uwsm-app -- ~/.config/hypr/scripts/battery-notify")
    hl.exec_cmd("uwsm-app -- kdeconnect-indicator")
    hl.exec_cmd("/usr/lib/kdeconnectd")
    hl.exec_cmd("sleep 1 && uwsm app -- waybar")
    hl.exec_cmd("~/.config/hypr/scripts/first-run")
    hl.exec_cmd("/usr/bin/throne")
    hl.exec_cmd("~/.config/hypr/scripts/launch-browser")
    hl.exec_cmd("/usr/bin/code")
    hl.exec_cmd("brave --app=https://claude.ai/new")
    hl.exec_cmd("brave --app=https://youtube.com")
    hl.exec_cmd("/usr/bin/obsidian")
end)

